examples.template:
MonarchPasskeyManager(
    passkeys,
    title: {{title}},
    description: {{description}},
    now: {{now|date}},
    onAdd: {
        // The app runs ASAuthorizationController and registers the key on its server.
        try await Task.sleep(for: .milliseconds(300))
    },
    onRename: { id, name in
        try await Task.sleep(for: .milliseconds(300))
    },
    onRemove: { id in
        try await Task.sleep(for: .milliseconds(300))
        passkeys.removeAll { $0.id == id }
    }
)

examples.setupTemplate:
@State private var passkeys = [
    MonarchPasskey(
        id: {{passkeys.0.id}},
        name: {{passkeys.0.name}},
        created: {{passkeys.0.createdAt|date}},
        lastUsed: {{passkeys.0.lastUsedAt|date}},
        isSynced: {{passkeys.0.synced}}
    ),
    MonarchPasskey(
        id: {{passkeys.1.id}},
        name: {{passkeys.1.name}},
        created: {{passkeys.1.createdAt|date}}
    ),
]

examples.code:
MonarchPasskeyManager(
    passkeys,
    title: "Passkeys",
    description: "Sign in with your fingerprint, face or screen lock instead of a password. Passkeys can’t be phished or reused.",
    now: Date(timeIntervalSince1970: 1_772_452_800),
    onAdd: {
        // The app runs ASAuthorizationController and registers the key on its server.
        try await Task.sleep(for: .milliseconds(300))
    },
    onRename: { id, name in
        try await Task.sleep(for: .milliseconds(300))
    },
    onRemove: { id in
        try await Task.sleep(for: .milliseconds(300))
        passkeys.removeAll { $0.id == id }
    }
)
